  48% { opacity: .78; transform: scale(.92); }
  52% { opacity: 1; transform: scale(1.06); }
}

h1 {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
  font-size: clamp(62px, 15.5vw, 164px);
  line-height: .82;
  letter-spacing: .02em;
  color: #e9e2cc;
  text-shadow:
    0 0 2px rgba(255,255,255,.4),
    0 0 34px rgba(255,196,40,.12),
