  display: block;
  color: #cfc5a9;
  font-size: .58em;
  letter-spacing: .34em;
  margin-top: .18em;
  text-indent: .34em;
  text-shadow: 0 0 30px rgba(255,196,40,.1), 0 10px 40px #000;
}

.tagline {
  margin: clamp(24px, 4.6vh, 42px) auto clamp(26px, 5vh, 46px);
  font-size: clamp(13px, 1.6vw, 16px);
  line-height: 1.75;
  letter-spacing: .16em;
  color: rgba(219,210,188,.7);
  text-transform: uppercase;
}

.primary {
  display: inline-block;
  min-width: 196px;
  padding: 16px 36px 15px;
  border: 1px solid rgba(255,210,58,.62);
  background:
    linear-gradient(180deg, rgba(255,210,58,.13), rgba(255,210,58,.03)),
    rgba(5,6,5,.4);
  color: var(--yellow-soft);
  font-size: 12px;
