  head.add(temple);
}

for (const side of [-1, 1]) {
  const nostril = new THREE.Mesh(new THREE.SphereGeometry(0.032, 8, 6), mats.black);
  nostril.position.set(side * 0.044, -0.135, 0.35);
  head.add(nostril);
}

// Fibrous wisps hang from the back of the skull.
const strandMat = new THREE.MeshStandardMaterial({ color: 0x9a9080, roughness: 0.96 });
const up = new THREE.Vector3(0, 1, 0);
for (let i = 0; i < 40; i++) {
  const a = rand(0, Math.PI * 2);
  const baseR = rand(0.16, 0.34);
  const bz = Math.sin(a) * baseR - 0.04;
  if (bz > 0.16) continue;
  const base = new THREE.Vector3(Math.cos(a) * baseR, rand(0.16, 0.37), bz);
  const dir = new THREE.Vector3(
    Math.cos(a) * rand(0.18, 0.62),
    -rand(0.12, 0.82),
    Math.sin(a) * rand(0.18, 0.62),
