import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport:{width:800,height:800} });
page.on('pageerror',e=>console.log('ERR',e.message));
await page.goto('http://localhost:3002/', {waitUntil:'load'});
await page.click('#startBtn');
await page.evaluate(()=>{ __SOUL_EYES__.state.grace=999; });
await page.waitForTimeout(300);
console.log(await page.evaluate(()=>{
  const d=__SOUL_EYES__.demon;
  return {eyeColors:d.eyeMats.map(m=>m.color.getHexString()), eyeTypes:d.eyeMats.map(m=>m.type), eyeCount:d.eyeMats.length, headScale:d.head.scale.toArray(), pos:d.group.position.toArray(), rot:d.group.rotation.y};
}));
const shot = async (name) => {
  // re-teleport every time: 3m in front along +z, look -z toward the demon
  await page.evaluate(()=>{
    const g=__SOUL_EYES__, d=g.demon.group.position, st=g.state;
    g.demon.state='dormant';
    st.pos.set(d.x, 0, d.z+3.0); st.yaw=0; st.pitch=0.24;
  });
  await page.waitForTimeout(600);
  await page.screenshot({path:'/tmp/opencode/'+name+'.png'});
};
await shot('eye2-normal');
// Hide glow sprites + point light, keep eye spheres
await page.evaluate(()=>{ const d=__SOUL_EYES__.demon; d.eyeGlows.forEach(s=>s.visible=false); d.eyeLight.visible=false; d.aura.visible=false; });
await shot('eye2-noglow');
// Magenta eyes to see sphere coverage
await page.evaluate(()=>{ __SOUL_EYES__.demon.eyeMats.forEach(m=>m.color.setHex(0xff00ff)); });
await shot('eye2-magenta');
// Hide rims: find torus objects and hide
await page.evaluate(()=>{ __SOUL_EYES__.demon.head.traverse(o=>{ if(o.isMesh && o.geometry.type==='TorusGeometry') o.visible=false; }); });
await shot('eye2-no-rim');
await browser.close();

