import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(runtime + '/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'));
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport:{width:1100,height:800} });
page.on('pageerror',e=>console.log('ERR',e.message));
await page.goto('http://localhost:3002/', {waitUntil:'load'});
await page.waitForTimeout(1200);
await page.screenshot({path:'/tmp/opencode/menu.png'});
// P pause/resume check
await page.click('#startBtn');
await page.waitForTimeout(500);
await page.keyboard.press('p');
await page.waitForTimeout(300);
console.log('after P:', await page.evaluate(()=>__SOUL_EYES__.state.mode));
await page.keyboard.press('p');
await page.waitForTimeout(300);
console.log('after P again:', await page.evaluate(()=>__SOUL_EYES__.state.mode));
await browser.close();
